document.addEventListener('click',e=>{const t=e.target.closest('[data-cdet]');if(t)return openDetail(+t.dataset.cdet);const f=e.target.closest('[data-it]');if(f)openItem(items[+f.dataset.it])});

/* ---------- goals on Overview: three live rings that feed each other ---------- */
const GCOL=['--gold','--violet','--ice'],GXR=[.96,.74,.52],GXA=[[.92,.1,.4],[.98,-.15,2.5],[.8,.2,4.6]];
const goalsX=()=>`<div class="panel edge gx rv" id="gx"><div class="gx-stage" id="gxStage"><canvas id="gxCv" aria-hidden="true"></canvas><div class="gx-mid" id="gxMid"><small></small><b class="num">0%</b><span></span></div>${[0,1,2].map(g=>`<span class="gx-tag" data-g="${g}" style="--c:var(${GCOL[g]})">${GOALS[g].k}</span>`).join('')}</div>
 <div class="gx-side"><div class="gx-list" id="gxList">${[2,1,0].map((g,n)=>{const G=GOALS[g],on=G.items.filter(x=>x[1]>=45).length;return `<a class="gx-row" href="#goals" data-g="${g}" data-card="g${g}" style="--c:var(${GCOL[g]})"><div class="gx-top"><i class="gx-dot"></i><div class="grow"><small>${G.k} &nbsp;·&nbsp; ${G.sub}</small><b>${G.head}</b></div><span class="gx-p num">${G.p}%</span></div><div class="gx-bar"><i style="--p:${G.p}%"></i></div><div class="gx-items"><div>${G.items.map(it=>`<div class="gx-it${it[1]>=100?' done':''}"><span class="gx-ck">${it[1]>=100?TICK:''}</span><span class="grow">${it[0]}</span><em class="num">${it[1]>=100?'Done':it[1]+'%'}</em></div>`).join('')}</div></div>${n<2?'<div class="gx-feed" aria-hidden="true"><i></i><i></i><i></i><span>feeds</span></div>':''}</a>`}).join('')}</div>
 <div class="gx-stats"><div><b class="num">1</b><span>goal finished this week</span></div><div><b class="num">7 of 9</b><span>goals on track</span></div><div><b class="num">45</b><span>days left in the quarter</span></div></div></div></div>`;
let gxF=2,gxHover=false,gxNext=0,gxShow=0,gxE=0,gxLook='',gxC=[],gxInk='',gxPulse=[0,0,0],gxFeed=null,gxFeedAt=0,gxMx=0,gxMy=0,gxTx=0,gxTy=0;
function setGx(g){gxF=g;$$('#gxList .gx-row').forEach(r=>r.classList.toggle('on',+r.dataset.g===g));const m=$('#gxMid');if(m){m.firstElementChild.textContent=GOALS[g].k;m.lastElementChild.textContent=GOALS[g].sub;m.style.setProperty('--c',`var(${GCOL[g]})`)}}
document.addEventListener('pointerover',e=>{const r=e.target.closest&&e.target.closest('.gx-row');if(r){gxHover=true;if(+r.dataset.g!==gxF)setGx(+r.dataset.g)}});
document.addEventListener('pointerout',e=>{const r=e.target.closest&&e.target.closest('.gx-row');if(r&&!(e.relatedTarget&&r.contains(e.relatedTarget))){gxHover=false;gxNext=last/1000+4}});
document.addEventListener('pointermove',e=>{const s=e.target.closest&&e.target.closest('.gx-stage');if(!s){gxTx=gxTy=0;return}const r=s.getBoundingClientRect();gxTx=(e.clientX-r.left)/r.width-.5;gxTy=(e.clientY-r.top)/r.height-.5},{passive:true});
function drawGx(t,dt){const cv=$('#gxCv');if(!cv)return;const rc=cv.getBoundingClientRect();if(!rc.width||rc.bottom<-60||rc.top>innerHeight+60)return;
  const dpr=Math.min(devicePixelRatio||1,2),w=rc.width,h=rc.height;if(cv.width!==Math.round(w*dpr)||cv.height!==Math.round(h*dpr)){cv.width=Math.round(w*dpr);cv.height=Math.round(h*dpr)}
  if(gxLook!==look){gxLook=look;gxC=GCOL.map(c=>css(c));gxInk=css('--ink')}
  const x=cv.getContext('2d');x.setTransform(dpr,0,0,dpr,0,0);x.clearRect(0,0,w,h);x.lineCap='round';
  const calm=still||reduce,e0=calm?1:clamp(1-(rc.top+h*.35-innerHeight*.5)/(innerHeight*.5),0,1);gxE=calm?1:gxE+(e0-gxE)*Math.min(1,dt*3.5);const ez=1-Math.pow(1-gxE,3);
  if(!gxHover&&!calm&&ez>.6&&t>gxNext){if(gxNext)setGx(gxF===2?1:gxF===1?0:2);gxNext=t+4.6}
  gxMx+=(gxTx-gxMx)*Math.min(1,dt*5);gxMy+=(gxTy-gxMy)*Math.min(1,dt*5);
  const cx=w/2,cy=h/2,S=Math.min(w,h)/2*.92,segs=[],heads=[],N=132,tt=calm?7.3:t;
  const pt=(g,th)=>{const A=GXA[g],al=A[0]+gxMy*.5+(1-ez)*.5,ph=A[2]+tt*A[1]+gxMx*.9,R=S*GXR[g]*(1+(1-ez)*(.2+g*.25)),ca=Math.cos(al),sa=Math.sin(al),cp=Math.cos(ph),sp=Math.sin(ph),c=Math.cos(th),s=Math.sin(th);
    const px=R*(-sp*c-ca*cp*s),py=R*(cp*c-ca*sp*s),pz=R*sa*s,k=1+pz/(S*5);return [cx+px*k,cy+py*k,pz/R]};
  for(let g=0;g<3;g++){const th0=tt*(.34-g*.13)+g*2.2,span=Math.PI*2*GOALS[g].p/100*ez;gxPulse[g]=Math.max(0,gxPulse[g]-dt*1.6);
    let p0=pt(g,th0);for(let k=1;k<=N;k++){const th=th0+k/N*Math.PI*2,p1=pt(g,th),lit=(k-.5)/N*Math.PI*2<=span;segs.push([(p0[2]+p1[2])/2,p0[0],p0[1],p1[0],p1[1],g,lit,lit?k/N*Math.PI*2/Math.max(.001,span):0]);p0=p1}
    heads[g]=pt(g,th0+span);
    for(let s=0;s<5;s++){const f=(tt*.16*(1+g*.3)+s/5)%1,p=pt(g,th0+span*f);segs.push([p[2]+.01,p[0],p[1],0,0,g,2,Math.sin(f*Math.PI)])}}
  segs.sort((a,b)=>a[0]-b[0]);
  for(const s of segs){const d=(s[0]+1)/2,g=s[5],foc=g===gxF,c=gxC[g];
    if(s[6]===2){x.fillStyle=hexA(c,(.35+.65*d)*s[7]*ez);x.beginPath();x.arc(s[1],s[2],(1.4+1.8*d)*(foc?1.25:1),0,7);x.fill();continue}
    x.beginPath();x.moveTo(s[1],s[2]);x.lineTo(s[3],s[4]);
    if(!s[6]){x.strokeStyle=`rgba(${gxInk},${(.1+.17*d)*ez})`;x.lineWidth=1.4+2.2*d;x.stroke();continue}
    const wd=(foc?9.5:6.5)*(.55+.6*d)*(1+gxPulse[g]*.7),al=(.3+.7*d)*(foc?1:.62)*(.45+.55*s[7])*ez;
    x.strokeStyle=hexA(c,al*.16);x.lineWidth=wd*3.2;x.stroke();x.strokeStyle=hexA(c,al);x.lineWidth=wd;x.stroke()}
  for(let g=0;g<3;g++){const p=heads[g],d=(p[2]+1)/2,r0=(g===gxF?9:6.5)*(.7+.5*d)*(1+gxPulse[g]),gr=x.createRadialGradient(p[0],p[1],0,p[0],p[1],r0*4.2);gr.addColorStop(0,hexA(gxC[g],.75*ez));gr.addColorStop(1,hexA(gxC[g],0));x.fillStyle=gr;x.beginPath();x.arc(p[0],p[1],r0*4.2,0,7);x.fill();x.fillStyle=`rgba(255,255,255,${.95*ez})`;x.beginPath();x.arc(p[0],p[1],r0*.55,0,7);x.fill()}
  if(!calm&&ez>.9){if(!gxFeed&&t>gxFeedAt)gxFeed={a:2,b:1,k:0};
    if(gxFeed){const f=gxFeed;f.k+=dt*1.15;const A=heads[f.a],Bp=heads[f.b],u=clamp(f.k,0,1),uu=u*u*(3-2*u);
      for(let j=0;j<9;j++){const q=clamp(uu-j*.035,0,1),mx=(A[0]+Bp[0])/2+(cx-(A[0]+Bp[0])/2)*.7,my=(A[1]+Bp[1])/2+(cy-(A[1]+Bp[1])/2)*.7,px=(1-q)*(1-q)*A[0]+2*q*(1-q)*mx+q*q*Bp[0],py=(1-q)*(1-q)*A[1]+2*q*(1-q)*my+q*q*Bp[1];x.fillStyle=j?hexA(gxC[f.a],.5*(1-j/9)):'rgba(255,255,255,.95)';x.beginPath();x.arc(px,py,j?3.2*(1-j/10):3.6,0,7);x.fill()}
      if(f.k>=1){gxPulse[f.b]=1;if(f.b===1)gxFeed={a:1,b:0,k:0};else{gxFeed=null;gxFeedAt=t+1.1}}}}
  $$('#gxStage .gx-tag').forEach(el=>{const g=+el.dataset.g,p=heads[g],dx=p[0]-cx,dy=p[1]-cy,L=Math.hypot(dx,dy)||1;el.style.transform=`translate(${clamp(p[0]+dx/L*30,48,rc.width-48).toFixed(1)}px,${clamp(p[1]+dy/L*24,16,rc.height-16).toFixed(1)}px) translate(-50%,-50%)`;el.style.opacity=ez*(g===gxF?1:.6)});
  const tg=GOALS[gxF].p*ez;gxShow=calm?tg:gxShow+(tg-gxShow)*Math.min(1,dt*6);const el=$('#gxMid b'),tx=Math.round(gxShow)+'%';if(el&&el.textContent!==tx)el.textContent=tx}

function mountOverview(){stopBrief();$('#ov').innerHTML=OV();drawDeck();gxNext=0;setGx(gxF);showBrief(0);mountNews();fillMade();tick();onScroll();if(reduce)frame(0)}
function setMode(m){mode=m;drawDeck()}
function openClient(i){csel=i;const c=CLIENTS[i];$('#csM').textContent=c.m;$('#csM').style.setProperty('--glow',GLOW[c.c]);$('#csT').textContent='Connect '+c.n;
  const rows=[['Website','web','Google Analytics · '+c.dom]].concat(c.src.map(s=>[SRCK[s[0]][0],SRCK[s[0]][1],s[0]+' · '+s[1]]));
  $('#csRows').innerHTML=rows.map(r=>`<label class="crow"><span class="sphere">${ic(r[1])}</span><span class="grow"><b>${r[0]}</b><small>${esc(r[2])}</small></span><input class="tg" type="checkbox" checked aria-label="Include ${r[0]}"></label>`).join('');
  $('#csheet').hidden=false;$('#csGo').focus()}
function closeClient(){$('#csheet').hidden=true}
function connectClient(i){const c=CLIENTS[i];c.on=true;cl=i;mode='clients';closeClient();drawDeck();toast(c.n+' is connected. It has its own space now.');scrollTo({top:0,behavior:reduce?'auto':'smooth'})}
$('#csX').onclick=$('#csCancel').onclick=closeClient;$('#csGo').onclick=()=>connectClient(csel);
$('#csheet').addEventListener('click',e=>{if(e.target.id==='csheet')closeClient()});
addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#csheet').hidden)closeClient()});
document.addEventListener('click',e=>{const q=s=>e.target.closest(s);let t;
  if(t=q('#modeSw button'))return setMode(t.dataset.m);
  if(t=q('.stab[data-tab]')){if(mode==='sites')site=t.dataset.tab;else cl=+t.dataset.tab;return drawDeck()}
  if(t=q('#metric button')){metric=t.dataset.m;return drawWeb()}
  if(t=q('#range button')){range=+t.dataset.r;return drawWeb()}
  if(q('[data-jump]')){const g=$('#cgrid');if(g)g.scrollIntoView({behavior:reduce?'auto':'smooth',block:'start'});return}
  if(!q('[data-notclient]')&&(t=q('[data-connect]')))return openClient(+t.dataset.connect);
  if(t=q('[data-notclient]')){const c=CLIENTS[+t.dataset.notclient];c.no=true;SKIPPED.push(c.n);drawDeck();return toast(c.n+' is left out. You can bring it back any time.')}});
document.addEventListener('submit',e=>{if(e.target.id!=='cAdd')return;e.preventDefault();const v=$('#cAddIn').value.trim();if(!v)return;
  CLIENTS.push({n:v,m:v.split(/\s+/).map(w=>w[0]).join('').slice(0,2).toUpperCase(),c:'--text-2',dom:'website not found yet',share:.06,src:[['You','Added by hand']],why:'Added by you. Your AI will look for a matching website, projects and files.',paid:0,owed:0,open:[0,0],reply:[0,'All answered']});openClient(CLIENTS.length-1)});
